            const isLabel = isCustomLabel(labelID, labels);
            await new Promise((resolve, reject) => {
                createModal(
                    <ConfirmModal
                        title={c('Title').t`Delete all messages`}
                        confirm={
                            <ErrorButton type="submit" data-testid="confirm-empty-folder">
